BEGIN;
WITH incoming AS (SELECT * FROM jsonb_to_recordset($catalog$[{"id": "8f0dca74-6a56-4652-8f33-e5bce41e367c", "name": "Zipper Hoodie — Black", "color": "Black", "color_hex": "#111111", "path": "8f0dca74-6a56-4652-8f33-e5bce41e367c/zipper.png"}, {"id": "0bfc3108-85f7-497b-8d37-a56b0f14e2d6", "name": "Zipper Hoodie — Grey", "color": "Grey", "color_hex": "#c4c5cb", "path": "0bfc3108-85f7-497b-8d37-a56b0f14e2d6/zipper.png"}, {"id": "57e6a02a-5b58-4fba-ace5-907bec182d92", "name": "Zipper Hoodie — Navy Blue", "color": "Navy Blue", "color_hex": "#16233e", "path": "57e6a02a-5b58-4fba-ace5-907bec182d92/zipper.png"}, {"id": "e9503a65-b287-4e03-823f-fb2fbd2cd021", "name": "Zipper Hoodie — Maroon", "color": "Maroon", "color_hex": "#561b28", "path": "e9503a65-b287-4e03-823f-fb2fbd2cd021/zipper.png"}]$catalog$::jsonb) AS x(id uuid,name text,color text,color_hex text,path text))
INSERT INTO public.products(id,category_id,name,description,price_cents,status,featured,department,storefront,currency,enquiry_only,inquiry_colours)
SELECT x.id,c.id,x.name,'Choose your size and quantity to order this zipper online. Add an optional customisation note for our team. Delivery across Pakistan is Rs. 300.',100000,'published',false,'unisex','hood','PKR',false,jsonb_build_array(jsonb_build_object('color',x.color,'color_hex',x.color_hex))
FROM incoming x JOIN public.categories c ON c.storefront='hood' AND c.slug='hood-zipper-hoodies'
ON CONFLICT(id) DO NOTHING;
WITH incoming AS (SELECT * FROM jsonb_to_recordset($catalog$[{"id": "8f0dca74-6a56-4652-8f33-e5bce41e367c", "name": "Zipper Hoodie — Black", "color": "Black", "color_hex": "#111111", "path": "8f0dca74-6a56-4652-8f33-e5bce41e367c/zipper.png"}, {"id": "0bfc3108-85f7-497b-8d37-a56b0f14e2d6", "name": "Zipper Hoodie — Grey", "color": "Grey", "color_hex": "#c4c5cb", "path": "0bfc3108-85f7-497b-8d37-a56b0f14e2d6/zipper.png"}, {"id": "57e6a02a-5b58-4fba-ace5-907bec182d92", "name": "Zipper Hoodie — Navy Blue", "color": "Navy Blue", "color_hex": "#16233e", "path": "57e6a02a-5b58-4fba-ace5-907bec182d92/zipper.png"}, {"id": "e9503a65-b287-4e03-823f-fb2fbd2cd021", "name": "Zipper Hoodie — Maroon", "color": "Maroon", "color_hex": "#561b28", "path": "e9503a65-b287-4e03-823f-fb2fbd2cd021/zipper.png"}]$catalog$::jsonb) AS x(id uuid,name text,color text,color_hex text,path text))
INSERT INTO public.product_images(product_id,path,color,alt,position) SELECT id,path,color,name,0 FROM incoming ON CONFLICT(path) DO NOTHING;
WITH incoming AS (SELECT * FROM jsonb_to_recordset($catalog$[{"id": "8f0dca74-6a56-4652-8f33-e5bce41e367c", "name": "Zipper Hoodie — Black", "color": "Black", "color_hex": "#111111", "path": "8f0dca74-6a56-4652-8f33-e5bce41e367c/zipper.png"}, {"id": "0bfc3108-85f7-497b-8d37-a56b0f14e2d6", "name": "Zipper Hoodie — Grey", "color": "Grey", "color_hex": "#c4c5cb", "path": "0bfc3108-85f7-497b-8d37-a56b0f14e2d6/zipper.png"}, {"id": "57e6a02a-5b58-4fba-ace5-907bec182d92", "name": "Zipper Hoodie — Navy Blue", "color": "Navy Blue", "color_hex": "#16233e", "path": "57e6a02a-5b58-4fba-ace5-907bec182d92/zipper.png"}, {"id": "e9503a65-b287-4e03-823f-fb2fbd2cd021", "name": "Zipper Hoodie — Maroon", "color": "Maroon", "color_hex": "#561b28", "path": "e9503a65-b287-4e03-823f-fb2fbd2cd021/zipper.png"}]$catalog$::jsonb) AS x(id uuid,name text,color text,color_hex text,path text))
INSERT INTO private.hood_packaged_assets(path) SELECT path FROM incoming ON CONFLICT DO NOTHING;
WITH incoming AS (SELECT * FROM jsonb_to_recordset($catalog$[{"id": "8f0dca74-6a56-4652-8f33-e5bce41e367c", "name": "Zipper Hoodie — Black", "color": "Black", "color_hex": "#111111", "path": "8f0dca74-6a56-4652-8f33-e5bce41e367c/zipper.png"}, {"id": "0bfc3108-85f7-497b-8d37-a56b0f14e2d6", "name": "Zipper Hoodie — Grey", "color": "Grey", "color_hex": "#c4c5cb", "path": "0bfc3108-85f7-497b-8d37-a56b0f14e2d6/zipper.png"}, {"id": "57e6a02a-5b58-4fba-ace5-907bec182d92", "name": "Zipper Hoodie — Navy Blue", "color": "Navy Blue", "color_hex": "#16233e", "path": "57e6a02a-5b58-4fba-ace5-907bec182d92/zipper.png"}, {"id": "e9503a65-b287-4e03-823f-fb2fbd2cd021", "name": "Zipper Hoodie — Maroon", "color": "Maroon", "color_hex": "#561b28", "path": "e9503a65-b287-4e03-823f-fb2fbd2cd021/zipper.png"}]$catalog$::jsonb) AS x(id uuid,name text,color text,color_hex text,path text))
INSERT INTO public.product_variants(product_id,color,color_hex,size,stock,active)
SELECT x.id,x.color,x.color_hex,s.size,10,true FROM incoming x CROSS JOIN (VALUES('S'),('M'),('L'),('XL'))s(size)
ON CONFLICT(product_id,color,size) DO NOTHING;
COMMIT;
